  'n1-1764': { ja: '大勢の前に出ると気後れしてしまう。', zh: '一站到眾人面前就會怯場。' },
  'n1-1765': { ja: 'あの子は物怖じせず大人と話せる。', zh: '那孩子毫不畏縮地跟大人說話。' },
