  'n1-1799': { ja: '祖父は頑固者で医者の言うことも聞かない。', zh: '祖父是個老頑固，連醫生的話都不聽。' },
  'n1-1800': { ja: '先生は誰からも尊敬される人格者だった。', zh: '老師是受所有人尊敬的人格高尚者。' },
