  'n1-1861': { ja: '冷やかしの客ばかりで全然売れない。', zh: '都是只看不買的客人，完全賣不出去。' },
  'n1-1862': { ja: '政府の対応を揶揄する風刺画が話題になった。', zh: '揶揄政府應對的諷刺畫成了話題。' },
  'n1-1863': { ja: '不当な扱いに社員たちは憤慨した。', zh: '員工們對不當待遇感到憤慨。' },
