  'n1-1875': { ja: '優勝の瞬間、監督は感涙にむせんだ。', zh: '奪冠瞬間，教練感動得熱淚盈眶。' },
  'n1-1876': { ja: '二十年ぶりの再会に感無量だった。', zh: '睽違二十年的重逢令人感慨萬千。' },
  'n1-1877': { ja: '彼は恍惚とした表情で音楽を聴いていた。', zh: '他帶著陶醉的表情聽著音樂。' },
