  'n1-2343': { ja: '彼の作品は時代を超越している。', zh: '他的作品超越了時代。' },
  'n1-2344': { ja: '一生をかけて罪を贖うつもりだ。', zh: '打算用一生來贖罪。' },
  'n1-2345': { ja: '己を厳しく律して生きる。', zh: '嚴格律己地生活。' },
